mapper.select:
        select  t.databus_name,t.databus_name databusName,t.business_type_cd,t.business_type_cd businessTypeCd,t.databus_id,t.databus_id databusId,t.bean_name,t.bean_name beanName,t.status_cd,t.status_cd statusCd,t.state,t.seq 
from c_business_databus t 
where 1 =1 

   and t.databus_name= #{databusName}


   and t.business_type_cd= #{businessTypeCd}


   and t.databus_id= #{databusId}


   and t.bean_name= #{beanName}


   and t.status_cd= #{statusCd}


   and t.state= #{state}


   and t.seq= #{seq}

order by t.create_time desc

   limit #{page}, #{row}

